#[derive(Clone,Copy,Default,Debug,PartialEq,Eq)]
struct Count{mul:u64,add:u64,unit:u64,iota:u64,weights:u64,outputs:u64,output_add:u64}
impl Count{fn json(self)->Value{json!({"nonunit_root_multiplies":self.mul,"data_add_sub":self.add,"unit_factors_skipped":self.unit,"fourth_root_multiplies_subset":self.iota,"coefficient_weight_multiplies":self.weights,"output_multiplies":self.outputs,"output_adds":self.output_add,"complete_multiplies":self.mul+self.weights+self.outputs,"complete_add_sub":self.add+self.output_add})}}
fn add(a:Fr,b:Fr,c:&mut Count)->Fr{c.add+=1;a+b}
fn sub(a:Fr,b:Fr,c:&mut Count)->Fr{c.add+=1;a-b}
struct Roots{v:Vec<Fr>}
impl Roots{
 fn new(n:usize,w:Fr)->Self{assert_eq!(w.pow(&[n as u64]),Fr::ONE);assert_ne!(w.pow(&[(n/2)as u64]),Fr::ONE);let mut x=Fr::ONE;Self{v:(0..n).map(|_|{let r=x;x*=w;r}).collect()}}
 fn product(&self,x:Fr,k:usize,c:&mut Count)->Fr{let k=k%self.v.len();if k==0{c.unit+=1;x}else{c.mul+=1;if k==self.v.len()/4||k==3*self.v.len()/4{c.iota+=1;}x*self.v[k]}}
}
fn radix2(x:&[Fr],roots:&Roots,stride:usize,c:&mut Count)->Vec<Fr>{
 let n=x.len();if n==1{return x.to_vec();}
 let e:Vec<_>=x.iter().step_by(2).copied().collect();let o:Vec<_>=x.iter().skip(1).step_by(2).copied().collect();
 let e=radix2(&e,roots,stride*2,c);let o=radix2(&o,roots,stride*2,c);let mut out=vec![Fr::ZERO;n];
 for k in 0..n/2{let t=roots.product(o[k],stride*k,c);out[k]=add(e[k],t,c);out[k+n/2]=sub(e[k],t,c);}out
}
fn split(x:&[Fr],roots:&Roots,stride:usize,c:&mut Count)->Vec<Fr>{
 let n=x.len();if n<=2{return radix2(x,roots,stride,c);}
 let e:Vec<_>=x.iter().step_by(2).copied().collect();let a:Vec<_>=x.iter().skip(1).step_by(4).copied().collect();let b:Vec<_>=x.iter().skip(3).step_by(4).copied().collect();
 let e=split(&e,roots,stride*2,c);let a=split(&a,roots,stride*4,c);let b=split(&b,roots,stride*4,c);let mut out=vec![Fr::ZERO;n];
 for k in 0..n/4{let t=roots.product(a[k],stride*k,c);let u=roots.product(b[k],stride*3*k,c);let s=add(t,u,c);let d=sub(t,u,c);let d=roots.product(d,stride*(n/4),c);out[k]=add(e[k],s,c);out[k+n/2]=sub(e[k],s,c);out[k+n/4]=add(e[k+n/4],d,c);out[k+3*n/4]=sub(e[k+n/4],d,c);}out
}
fn transform(x:&[Fr],roots:&Roots,split_mode:bool,c:&mut Count)->Vec<Fr>{if split_mode{split(x,roots,1,c)}else{radix2(x,roots,1,c)}}
fn af(x:Fr)->ark_bn254::Fr{ark_bn254::Fr::from_be_bytes_mod_order(&x.to_be_bytes())}
fn direct(x:&[ark_bn254::Fr],w:ark_bn254::Fr)->Vec<ark_bn254::Fr>{let mut step=ark_bn254::Fr::ONE;(0..x.len()).map(|_|{let mut a=ark_bn254::Fr::ZERO;let mut p=ark_bn254::Fr::ONE;for v in x{a+=*v*p;p*=step;}step*=w;a}).collect()}
fn rnd(s:&mut u64)->u64{*s^=*s<<13;*s^=*s>>7;*s^=*s<<17;*s}
fn random(s:&mut u64)->Fr{let mut b=[0;64];for c in b.chunks_exact_mut(8){c.copy_from_slice(&rnd(s).to_le_bytes());}Fr::from_random_bytes(&b)}
fn count_rec(n:u64,mode:bool)->(u64,u64,u64){if n==1{return(0,0,0);}if n==2{return(0,2,1);}if mode{let a=count_rec(n/2,true);let b=count_rec(n/4,true);(a.0+2*b.0+3*n/4-2,a.1+2*b.1+3*n/2,a.2+2*b.2+2)}else{let a=count_rec(n/2,false);(2*a.0+n/2-1,2*a.1+n,2*a.2+1)}}
fn count_dp(log:u32,mode:bool)->(u64,u64,u64){let mut v=vec![(0,0,0),(0,2,1)];for l in 2..=log{let n=1u64<<l;let a=v[l as usize-1];let z=if mode{let b=v[l as usize-2];(a.0+2*b.0+3*n/4-2,a.1+2*b.1+3*n/2,a.2+2*b.2+2)}else{(2*a.0+n/2-1,2*a.1+n,2*a.2+1)};v.push(z);}v[log as usize]}
fn euler(a:&[Fr],b:&[Fr],roots:&Roots,inverse:&Roots,mode:bool)->(Vec<Fr>,Count){
 let len=a.len().max(b.len());let n=roots.v.len();let mut c=Count::default();if len==0{return(Vec::new(),c);}
 let mut aa=a.to_vec();let mut bb=b.to_vec();aa.resize(n,Fr::ZERO);bb.resize(n,Fr::ZERO);
 let mut ca=transform(&aa,inverse,mode,&mut c);let mut cb=transform(&bb,inverse,mode,&mut c);
 for j in 0..n{let k=Fr::from(j as u64);ca[j]*=k;cb[j]*=k;c.weights+=2;}
 let da=transform(&ca,roots,mode,&mut c);let db=transform(&cb,roots,mode,&mut c);
 let out=(0..len).map(|j|{c.outputs+=2;c.output_add+=1;da[j]*bb[j]+aa[j]*db[j]}).collect();(out,c)
}
fn oracle_euler(a:&[Fr],b:&[Fr],w:Fr,n:usize)->Vec<ark_bn254::Fr>{let len=a.len().max(b.len());if len==0{return vec![];}let mut a:Vec<_>=a.iter().copied().map(af).collect();let mut b:Vec<_>=b.iter().copied().map(af).collect();a.resize(n,ark_bn254::Fr::ZERO);b.resize(n,ark_bn254::Fr::ZERO);let w=af(w);let wi=w.inverse().unwrap();let ni=ark_bn254::Fr::from(n as u64).inverse().unwrap();let derivative=|x:&[ark_bn254::Fr]|{let mut c=direct(x,wi);for(k,x)in c.iter_mut().enumerate(){*x*=ni*ark_bn254::Fr::from(k as u64);}direct(&c,w)};let da=derivative(&a);let db=derivative(&b);(0..len).map(|j|ark_bn254::Fr::from(n as u64)*(da[j]*b[j]+a[j]*db[j])).collect()}
fn sparse(terms:&[(usize,u64)],w:Fr,n:usize)->(Vec<Fr>,Vec<ark_bn254::Fr>){let mut values=vec![Fr::ZERO;n];let mut deriv=vec![ark_bn254::Fr::ZERO;n];for&(k,c)in terms{let step=w.pow(&[k as u64]);let astep=af(w).pow([k as u64]);let mut v=Fr::from(c);let mut d=ark_bn254::Fr::from(c)*ark_bn254::Fr::from(k as u64);for j in 0..n{values[j]+=v;deriv[j]+=d;v*=step;d*=astep;}}(values,deriv)}
